/* ---------------------------------------------------------------- engine */
const strip=s=>String(s==null?"":s).replace(/​/g,"").trim();
const def=(o,k,v)=>{try{Object.defineProperty(o,k,{configurable:true,enumerable:true,writable:true,value:v})}catch(e){try{o[k]=v}catch(x){}}};
const stopOf=(id,title)=>{try{const t=PS_TOURS[id];return t&&Array.isArray(t.steps)?t.steps.find(s=>s&&strip(s.title)===title):null}catch(e){return null}};
const MAXPH=5,COL="#d9682b";
const fileOf=f=>f&&f[0]==="@"?(NEW[f.slice(1)]||""):f;
function libIdx(f){try{if(!f||typeof PS_PHOTO_DATA==="undefined")return -1;for(let i=0;i<PS_PHOTO_DATA.length;i++){const x=PS_PHOTO_DATA[i];if(x&&x.f===f&&x.d)return i}}catch(e){}return -1}
function merge(){try{if(typeof PS_PHOTO_DATA==="undefined")return;const have=new Set(PS_PHOTO_DATA.filter(p=>p&&p.d).map(p=>p.f));
 GF_WILD_PHOTOS.forEach(p=>{if(!have.has(p.f)){PS_PHOTO_DATA.push(p);have.add(p.f)}})}catch(e){}}
const picOf=q=>{try{const P=typeof psSqPhoto==="function"?psSqPhoto(q):null;return P&&P.d?P.f:null}catch(e){return null}};
/* the photo pins of one stop: the ones already there first, then ours up to five in all */
function photos(id,S,card){const plan=PLAN[id+"|"+strip(S.title)];if(!plan||!plan.p.length)return false;
 const cur=Array.isArray(S.phPins)?S.phPins:[],others=cur.filter(q=>!(q&&q._gfWild)),mine=cur.filter(q=>q&&q._gfWild);
 const files=new Set(others.map(picOf).filter(Boolean)),names=new Set(others.map(q=>strip(q&&q.label).toLowerCase()));
 if(card)files.add(card);
 const near=(a,b)=>Math.abs(a[0]-b[0])<.05&&Math.abs(a[1]-b[1])<.05;
 const want=[];for(const [lab,at,f] of plan.p){if(others.length+want.length>=MAXPH)break;const file=fileOf(f),i=libIdx(file);if(i<0)continue;
  if(files.has(file)||names.has(lab.toLowerCase()))continue;
  if(others.some(q=>q&&Array.isArray(q.at)&&near(q.at,at)&&strip(q.label).toLowerCase()===lab.toLowerCase()))continue;
  files.add(file);names.add(lab.toLowerCase());
  try{window.PS_SQ_IMG=window.PS_SQ_IMG||{};if(PS_SQ_IMG[lab]==null)PS_SQ_IMG[lab]=i;window.GF_PHCAP=window.GF_PHCAP||{};if(!GF_PHCAP[lab])GF_PHCAP[lab]=lab}catch(e){}
  const old=mine.find(q=>strip(q.label)===lab);
  want.push(old&&old._gfImg===i?old:{at:at.slice(),label:lab,col:(others.find(q=>q&&q.icon==="photo"&&q.col)||{}).col||COL,icon:"photo",_gfWild:1,_gfImg:i,_gfF:file})}
 const next=others.concat(want);if(next.length===cur.length&&next.every((q,k)=>q===cur[k]))return false;
 /* a field another patch has locked (a getter that ignores writes, as in geoflock-polish-l.js) stays locked, so the pins it
    protects are not lost to a later write; otherwise it stays a plain writable field */
 let d=null;try{d=Object.getOwnPropertyDescriptor(S,"phPins")}catch(e){}
 if(d&&d.get){try{Object.defineProperty(S,"phPins",{configurable:true,enumerable:true,get(){return next},set(){}})}catch(e){def(S,"phPins",next)}}else def(S,"phPins",next);
 S._sqPruned=-1;return true}
/* the symbols of one stop (only a stop with no symbols of its own) */
function symbols(id,S){const plan=PLAN[id+"|"+strip(S.title)];if(!plan||!plan.s.length)return false;
 if(S.gfSym)return false;
 def(S,"gfSym",{marks:plan.s.map(([e,at,name])=>({at:at.slice(),e:"gfw_"+e,sz:19,reach:1.3,gap:4,_gfw:e,_n:name}))});
 try{const st=PS_TOURS[id].steps;if(!st._gfSym)def(st,"_gfSym",1)}catch(e){}
 return true}
/* the layer of geoflock-symbols.js draws <img src="data:image/svg+xml,"> for a name it does not know: give it the picture */
const URI={};const uri=k=>URI[k]||(URI[k]="data:image/svg+xml,"+encodeURIComponent(TW[k]||""));
function paint(){try{if(typeof ps==="undefined"||!ps||typeof psSteps!=="function")return;const S=psSteps()[ps.i];
 const box=typeof psContainer==="function"&&psContainer();if(!box)return;const lay=box.querySelector(".gfs-lay");if(!lay)return;
 const M=S&&S.gfSym&&S.gfSym.marks;if(!M||!M.some(m=>m&&m._gfw))return;
 const els=lay.querySelectorAll(":scope > .gfs-m");M.forEach((m,k)=>{const el=els[k];if(!el||!m._gfw)return;const im=el.querySelector("img");
  if(im&&!im._gfw){im.src=uri(m._gfw);im.alt=m._n||"";im._gfw=1;el.title=m._n||""}})}catch(e){}}
let mo=null,moBox=null;
function watch(){try{const box=typeof psContainer==="function"&&psContainer();if(!box||box===moBox)return;if(mo)mo.disconnect();
 mo=new MutationObserver(paint);mo.observe(box,{childList:true});moBox=box}catch(e){}}
